{
  "bioavailability_prediction": "low",
  "confidence": "high",
  "revision_action": "strengthen",
  "supportive_card_ids": ["C06", "C31", "C27", "C02", "C05", "C30", "C42", "C34", "C35", "C36", "C41", "C58"],
  "contradictory_card_ids": ["C09", "C01", "C24", "C33", "C46"],
  "prediction_basis_card_ids": ["C06", "C31", "C27", "C02", "C05", "C30", "C58"],
  "claims": [
    {
      "claim": "The query is estradiol 17β-cyclopentylpropionate, a highly lipophilic 17-ester prodrug of estradiol; estradiol itself has approximately 5% oral bioavailability due to gut and liver metabolism, and the ester adds no solubilizing or metabolically protective group.",
      "card_ids": ["C06"]
    },
    {
      "claim": "Closely related estradiol derivatives have low oral F: 2-methoxyestradiol showed 1-2% in clinical studies and 3.04% in rats, attributed to poor solubility and first-pass metabolism.",
      "card_ids": ["C31", "C32", "C12", "C19"]
    },
    {
      "claim": "Other lipophilic steroids with poor solubility remain below 20%: progesterone is about 5% bioavailable in humans, and danazol is 11-19% fasted and 17±3.4% even with 1000 mL water.",
      "card_ids": ["C27", "C06", "C02", "C05", "C30", "C42"]
    },
    {
      "claim": "The new L3 oral-exposure record for estradiol (C58) shows low unconjugated estradiol Cmax (13.3 pg/mL) after oral dosing, consistent with low oral estradiol exposure; the ethinyl estradiol Cmax records (C49, C51, C54, C57, C59) reflect the metabolically protected 17α-ethinyl analog and are not transferable to the query.",
      "card_ids": ["C58", "C49", "C51", "C54", "C57", "C59"]
    },
    {
      "claim": "High-F analogs such as ethinyl estradiol (51±9%) and estramustine phosphate (34.9-45.0%) carry protective or solubilizing groups absent in the query, so they do not support F≥20%.",
      "card_ids": ["C09", "C01", "C24", "C25"]
    }
  ],
  "new_evidence_assessment": [
    {
      "family": "oral_auc_cmax_exposure",
      "applicability": "moderate",
      "direction": "supportive",
      "decision_effect": "strengthened",
      "card_ids": ["C49", "C50", "C51", "C52", "C53", "C54", "C55", "C56", "C57", "C58", "C59", "C60"]
    }
  ],
  "evidence_gaps": [
    "No direct oral bioavailability measurement for estradiol cypionate itself.",
    "Dose, formulation, and prandial state for the query are unspecified; a lipophilic ester could in principle engage lymphatic absorption, but no direct evidence supports this.",
    "L3 records are oral exposure (Cmax/Cτ) rather than absolute F, and most are for ethinyl estradiol, not the query ester.",
    "C58 is from a conjugated estrogen product (Cenestin), not estradiol cypionate, so its quantitative relevance is limited.",
    "Prodrug hydrolysis rate and first-pass metabolism of the cyclopentylpropionate ester are not directly evidenced."
  ],
  "decision_summary": "Predicted low with high confidence: the query is an estradiol 17-ester prodrug, and the most transferable steroid evidence (estradiol ~5%, 2-methoxyestradiol 1-2%, progesterone ~5%, danazol 11-19%) supports F below 20%. The L3 oral-exposure records are consistent with this: the estradiol exposure record shows low oral estradiol Cmax, while the ethinyl estradiol Cmax records reflect a metabolically protected analog that is not transferable to the query. No new evidence overturns the prior low decision."
}

